head.script:
scwin.screenId = "jldstf31202";

///////// 1. 변수 및 선언 영역 /////////

scwin.frame = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_O_INITDATE", fn: function(){ return (!(String(((dma_Cal3.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal3.O_INITDATE"); })())) == null ? '' : ((dma_Cal3.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal3.O_INITDATE"); })()))).length === 0)); } }, { id: "tr_142", fn: function(){ return (!(String(((dma_Cal3.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal3.O_INITDATE"); })())) == null ? '' : ((dma_Cal3.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal3.O_INITDATE"); })()))).length === 0)); } }, { id: "if_ERROR_MSG", fn: function(){ return ((String(((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })())) == null ? '' : ((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })()))).length === 0)); } }, { id: "tr_147", fn: function(){ return ((String(((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })())) == null ? '' : ((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })()))).length === 0)); } }, { id: "tr_151", fn: function(){ return ((String(((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })())) == null ? '' : ((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })()))).length === 0)); } }, { id: "tr_155", fn: function(){ return ((String(((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })())) == null ? '' : ((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })()))).length === 0)); } }, { id: "tr_160", fn: function(){ return ((String(((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })())) == null ? '' : ((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })()))).length === 0)); } }, { id: "tr_165", fn: function(){ return ((String(((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })())) == null ? '' : ((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })()))).length === 0)); } }, { id: "if_ERROR_MSG_2", fn: function(){ return (!(String(((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })())) == null ? '' : ((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })()))).length === 0)); } }, { id: "tr_171", fn: function(){ return (!(String(((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })())) == null ? '' : ((dma_Cal3.get("ERROR_MSG") ?? (() => { throw new Error("unresolved:" + "Cal3.ERROR_MSG"); })()))).length === 0)); } }, { id: "if_O_INITDATE_2", fn: function(){ return (!(String(((dma_Cal4.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal4.O_INITDATE"); })())) == null ? '' : ((dma_Cal4.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal4.O_INITDATE"); })()))).length === 0)); } }, { id: "tr_283", fn: function(){ return (!(String(((dma_Cal4.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal4.O_INITDATE"); })())) == null ? '' : ((dma_Cal4.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal4.O_INITDATE"); })()))).length === 0)); } }, { id: "if_O_INITDATE_3", fn: function(){ return (!(String(((dma_Cal5.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal5.O_INITDATE"); })())) == null ? '' : ((dma_Cal5.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal5.O_INITDATE"); })()))).length === 0)); } }, { id: "tr_406", fn: function(){ return (!(String(((dma_Cal5.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal5.O_INITDATE"); })())) == null ? '' : ((dma_Cal5.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal5.O_INITDATE"); })()))).length === 0)); } }, { id: "if_O_INITDATE_4", fn: function(){ return (!(String(((dma_Cal7.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal7.O_INITDATE"); })())) == null ? '' : ((dma_Cal7.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal7.O_INITDATE"); })()))).length === 0)); } }, { id: "tr_591", fn: function(){ return (!(String(((dma_Cal7.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal7.O_INITDATE"); })())) == null ? '' : ((dma_Cal7.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal7.O_INITDATE"); })()))).length === 0)); } }, { id: "if_O_INITDATE_5", fn: function(){ return (!(String(((dma_Cal8.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal8.O_INITDATE"); })())) == null ? '' : ((dma_Cal8.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal8.O_INITDATE"); })()))).length === 0)); } }, { id: "tr_700", fn: function(){ return (!(String(((dma_Cal8.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal8.O_INITDATE"); })())) == null ? '' : ((dma_Cal8.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal8.O_INITDATE"); })()))).length === 0)); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "ㆍ기산일(이사회결의 전일) : " + String(dma_Cal3.get("O_INITDATE")); } },
        { childId: "__rb1", fn: function () { return "에러메세지 : " + String(dma_Cal3.get("ERROR_MSG")); } },
        { childId: "__rb2", fn: function () { return "ㆍ기산일 : " + String(dma_Cal4.get("O_INITDATE")); } },
        { childId: "__rb3", fn: function () { return "ㆍ기산일(이사회결의 전일) : " + String(dma_Cal7.get("O_INITDATE")); } },
        { childId: "__rb4", fn: function () { return "ㆍ기산일(이사회결의 전일) : " + String(dma_Cal8.get("O_INITDATE")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const ISU_CD = $c.util.getCookie("ISU_CD");
    const COM_NM = $c.util.getCookie("COM_NM");
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", COM_NM);
    if ($c.util.getComponent('rd_sellRestrict').getValue() === '0') {
        $c.util.getComponent('txt_idCal81').setLabel("1개월 가중산술평균주가");
        $c.util.getComponent('txt_idCal82').setLabel("1주일 가중산술평균주가");
        $c.util.getComponent('txt_idCal83').setLabel("최근일 가중산술평균주가");
    } else {
        $c.util.getComponent('txt_idCal81').setLabel("1개월 평균종가");
        $c.util.getComponent('txt_idCal82').setLabel("1주일 평균종가");
        $c.util.getComponent('txt_idCal83').setLabel("최근일 종가");
    }
    /* sdd-asis-lifecycle:end */
};


// [A] 초기 목록 미해결 — jldstf31202: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.form_frmISU_CD = { action: "", method: 'post', target: '' };

scwin.pathname = undefined; try { scwin.pathname = /* sdd-asis-lifecycle:begin pathname — as-is 원문 본문(전환 이관 · 포팅 적용됨) */location.pathname/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31202' }); }

scwin.qry = undefined; try { scwin.qry = /* sdd-asis-lifecycle:begin qry — as-is 원문 본문(전환 이관 · 포팅 적용됨) */location.search/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31202' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf31202.onpageload' });
    }
};


