/**
 * @method
 * @name scwin.cal3
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.cal3 = async function () {
    /* sdd-asis-lifecycle:begin fn_Cal3 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').focus ? $c.util.getComponent('ipt_ISU_CD').focus() : console.warn('[sdd] focus 대상 미해결: ipt_ISU_CD')));
        return;
    }
    if (($c.util.getComponent('cal_bodResolDd').getValue() == null ? '' : String($c.util.getComponent('cal_bodResolDd').getValue())) === '') {
        await $c.win.alert("[이사회결의일  ]을 입력하세요.");
        $c.util.getComponent("cal_bodResolDd").focus();
        return;
    }
    if (($c.util.getComponent('ipt_newIsuShrs').getValue() == null ? '' : String($c.util.getComponent('ipt_newIsuShrs').getValue())) === '') {
        await $c.win.alert("[신발행주식수 ]을 입력하세요.");
        $c.util.getComponent("ipt_newIsuShrs").focus();
        return;
    }
    if (($c.util.getComponent('ipt_oldIsuShrs').getValue() == null ? '' : String($c.util.getComponent('ipt_oldIsuShrs').getValue())) === '') {
        await $c.win.alert("[기발행주식수   ]을 입력하세요.");
        $c.util.getComponent("ipt_oldIsuShrs").focus();
        return;
    }
    if (($c.util.getComponent('ipt_dcRate').getValue() == null ? '' : String($c.util.getComponent('ipt_dcRate').getValue())) === '') {
        await $c.win.alert("[할인율  ]을 입력하세요.");
        $c.util.getComponent("ipt_dcRate").focus();
        return;
    }
    if ($c.util.getComponent('ipt_rdRate2').getValue()=== "0") {
        await $c.win.alert("'0'은 입력할수 없습니다.");
        $c.util.getComponent("ipt_rdRate2").focus();
        return;
    }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    $c.util.getComponent('dma_Cal3Req').set('method', "processCalculateRelatedDisclosure3");
    await scwin.tx_fn_Cal3();
    /* sdd-asis-lifecycle:end */
};


